using System;
using System.Drawing;
using System.Drawing.Drawing2D;
using System.IO;
using System.Windows.Forms;
using Guna.UI2.WinForms;

namespace Temo_Mobile_Store
{
    public class LoginForm : Form
    {
        private static readonly Color ColorPrimary = Color.FromArgb(26, 43, 76);
        private static readonly Color ColorAccent = Color.FromArgb(41, 98, 189);
        private static readonly Color ColorDanger = Color.FromArgb(231, 76, 60);
        private static readonly Color ColorPageBgTop = Color.FromArgb(235, 241, 250);
        private static readonly Color ColorPageBgBottom = Color.FromArgb(214, 227, 245);

        private Guna2TextBox txtUsername;
        private Guna2TextBox txtPassword;
        private Label lblError;

        // ---------- لوجو Temo Mobile Store مضمّن جوه الكود نفسه (Base64) ----------
        private const string LogoBase64 =
            "";

        public LoginForm()
        {
            this.Text = "تسجيل الدخول - Temo Mobile Store";
            this.Size = new Size(460, 760);
            this.StartPosition = FormStartPosition.CenterScreen;
            this.RightToLeft = RightToLeft.Yes;
            this.RightToLeftLayout = true;
            this.FormBorderStyle = FormBorderStyle.FixedDialog;
            this.MaximizeBox = false;
            this.MinimizeBox = false;

            BuildLayout();
        }

        protected override void OnPaintBackground(PaintEventArgs e)
        {
            // خلفية متدرجة بسيطة من الأزرق الفاتح جدًا لأزرق فاتح شوية - آمنة ومريحة للعين
            using (LinearGradientBrush brush = new LinearGradientBrush(
                this.ClientRectangle, ColorPageBgTop, ColorPageBgBottom, 55f))
            {
                e.Graphics.FillRectangle(brush, this.ClientRectangle);
            }
        }

        private void BuildLayout()
        {
            int centerX = this.ClientSize.Width / 2;

            // ---------- الكارت الأبيض ----------
            Guna2Panel card = new Guna2Panel
            {
                Location = new Point(30, 30),
                Size = new Size(this.ClientSize.Width - 60, this.ClientSize.Height - 90),
                FillColor = Color.White,
                BorderRadius = 20
            };

            // ---------- اللوجو ----------
            PictureBox picLogo = new PictureBox
            {
                Size = new Size(120, 120),
                Location = new Point((card.Width - 120) / 2, 25),
                SizeMode = PictureBoxSizeMode.Zoom,
                BackColor = Color.Transparent
            };
            try
            {
                byte[] logoBytes = Convert.FromBase64String(LogoBase64);
                using (var ms = new MemoryStream(logoBytes))
                    picLogo.Image = Image.FromStream(ms);
            }
            catch { }

            Label lblWelcome = new Label
            {
                Text = "مرحباً بك في نظام إدارة المحل",
                Location = new Point(0, 158),
                Size = new Size(card.Width, 28),
                TextAlign = ContentAlignment.MiddleCenter,
                Font = new Font("Segoe UI", 13, FontStyle.Bold),
                ForeColor = ColorPrimary
            };

            Label lblSubtitle = new Label
            {
                Text = "يرجى تسجيل الدخول للمتابعة",
                Location = new Point(0, 188),
                Size = new Size(card.Width, 22),
                TextAlign = ContentAlignment.MiddleCenter,
                Font = new Font("Segoe UI", 9.5F),
                ForeColor = Color.FromArgb(120, 128, 140)
            };

            int fieldsLeft = 35;
            int fieldsWidth = card.Width - 70;

            Label lblUser = new Label { Text = "اسم المستخدم", Location = new Point(fieldsLeft, 235), AutoSize = true, Font = new Font("Segoe UI", 9F, FontStyle.Bold), ForeColor = ColorPrimary };
            txtUsername = new Guna2TextBox
            {
                Location = new Point(fieldsLeft, 258),
                Width = fieldsWidth,
                Height = 42,
                BorderRadius = 10,
                FillColor = Color.FromArgb(248, 249, 251),
                BorderColor = Color.FromArgb(225, 230, 240),
                Font = new Font("Segoe UI", 10),
                PlaceholderText = "أدخل اسم المستخدم"
            };

            Label lblPass = new Label { Text = "كلمة المرور", Location = new Point(fieldsLeft, 312), AutoSize = true, Font = new Font("Segoe UI", 9F, FontStyle.Bold), ForeColor = ColorPrimary };
            txtPassword = new Guna2TextBox
            {
                Location = new Point(fieldsLeft, 335),
                Width = fieldsWidth,
                Height = 42,
                BorderRadius = 10,
                FillColor = Color.FromArgb(248, 249, 251),
                BorderColor = Color.FromArgb(225, 230, 240),
                Font = new Font("Segoe UI", 10),
                PasswordChar = (char)0x25CF,
                PlaceholderText = "أدخل كلمة المرور"
            };

            CheckBox chkRemember = new CheckBox
            {
                Text = "تذكرني",
                Location = new Point(fieldsLeft, 390),
                AutoSize = true,
                Font = new Font("Segoe UI", 9F),
                ForeColor = Color.FromArgb(90, 98, 110)
            };

            lblError = new Label
            {
                Text = "",
                Location = new Point(fieldsLeft, 418),
                Size = new Size(fieldsWidth, 36),
                TextAlign = ContentAlignment.MiddleCenter,
                ForeColor = ColorDanger,
                Font = new Font("Segoe UI", 8.5F, FontStyle.Bold)
            };

            Guna2Button btnLogin = new Guna2Button
            {
                Text = "🔒  تسجيل الدخول",
                Location = new Point(fieldsLeft, 460),
                Width = fieldsWidth,
                Height = 48,
                FillColor = ColorAccent,
                BorderRadius = 12,
                Font = new Font("Segoe UI", 11, FontStyle.Bold)
            };
            btnLogin.Click += BtnLogin_Click;

            Label lblDividerLine = new Label { BorderStyle = BorderStyle.Fixed3D, Location = new Point(fieldsLeft, 530), Size = new Size(fieldsWidth, 1), BackColor = Color.FromArgb(230, 233, 240) };
            Label lblOr = new Label { Text = "أو", Location = new Point(card.Width / 2 - 15, 520), Size = new Size(30, 20), TextAlign = ContentAlignment.MiddleCenter, BackColor = Color.White, ForeColor = Color.FromArgb(150, 158, 172), Font = new Font("Segoe UI", 8.5F) };

            Label lblTrust1 = new Label { Text = "🛡️ آمن وسريع", Location = new Point(fieldsLeft, 552), AutoSize = true, Font = new Font("Segoe UI", 8.5F, FontStyle.Bold), ForeColor = ColorAccent };
            Label lblTrust1Sub = new Label { Text = "بياناتك محمية بالكامل", Location = new Point(fieldsLeft, 572), AutoSize = true, Font = new Font("Segoe UI", 7.5F), ForeColor = Color.FromArgb(150, 158, 172) };

            Label lblTrust2 = new Label { Text = "🎧 تحتاج مساعدة؟", Location = new Point(fieldsLeft + fieldsWidth - 150, 552), Size = new Size(150, 18), TextAlign = ContentAlignment.MiddleRight, Font = new Font("Segoe UI", 8.5F, FontStyle.Bold), ForeColor = ColorAccent, Cursor = Cursors.Hand };
            Label lblTrust2Sub = new Label { Text = "تواصل مع الدعم الفني", Location = new Point(fieldsLeft + fieldsWidth - 150, 572), Size = new Size(150, 18), TextAlign = ContentAlignment.MiddleRight, Font = new Font("Segoe UI", 7.5F), ForeColor = Color.FromArgb(150, 158, 172), Cursor = Cursors.Hand };

            EventHandler openSupportWhatsApp = (s, e) =>
                WhatsAppHelper.SendMessage("01147114296", "مرحبًا، محتاج مساعدة في برنامج Temo Mobile Store", this);
            lblTrust2.Click += openSupportWhatsApp;
            lblTrust2Sub.Click += openSupportWhatsApp;

            card.Controls.AddRange(new Control[] {
                picLogo, lblWelcome, lblSubtitle,
                lblUser, txtUsername, lblPass, txtPassword, chkRemember, lblError, btnLogin,
                lblDividerLine, lblOr, lblTrust1, lblTrust1Sub, lblTrust2, lblTrust2Sub
            });

            Label lblFooter = new Label
            {
                Text = "Temo Mobile Store © 2026",
                Location = new Point(0, this.ClientSize.Height - 32),
                Size = new Size(this.ClientSize.Width, 22),
                TextAlign = ContentAlignment.MiddleCenter,
                Font = new Font("Segoe UI", 8.5F),
                ForeColor = ColorPrimary
            };

            this.AcceptButton = btnLogin;
            this.Controls.AddRange(new Control[] { card, lblFooter });
        }

        private void BtnLogin_Click(object sender, EventArgs e)
        {
            if (string.IsNullOrWhiteSpace(txtUsername.Text) || string.IsNullOrWhiteSpace(txtPassword.Text))
            {
                lblError.Text = "من فضلك أدخل اسم المستخدم وكلمة المرور.";
                return;
            }

            bool isDefaultAdminLogin = AuthManager.IsDefaultAdminLogin(txtUsername.Text, txtPassword.Text);

            string role = AuthManager.TryLogin(txtUsername.Text, txtPassword.Text);
            if (role == null)
            {
                lblError.Text = "اسم المستخدم أو كلمة المرور غلط.";
                txtPassword.Clear();
                txtPassword.Focus();
                return;
            }

            if (isDefaultAdminLogin)
            {
                using (ForceChangePasswordForm changeForm = new ForceChangePasswordForm(AuthManager.CurrentUsername))
                {
                    if (changeForm.ShowDialog() != DialogResult.OK)
                    {
                        lblError.Text = "لازم تغيّر كلمة المرور الافتراضية قبل ما تكمل.";
                        txtPassword.Clear();
                        txtPassword.Focus();
                        return;
                    }
                }
            }

            this.DialogResult = DialogResult.OK;
            this.Close();
        }
    }
}
